window.ELECPREP = {"title": "Block 4 · Electricity Exam Prep", "passMark": 0.7, "mockSize": 60, "storeKey": "blk4-elec-exam-v1", "figs": {"4": "data:image/png;base64,", "6": "data:image/png;base64,", "7": "data:image/png;base64,", "8": "data:image/png;base64,", "10": "data:image/png;base64,", "64": "data:image/png;base64,", "11": "data:image/png;base64,", "12": "data:image/png;base64,", "13": "data:image/png;base64,", "14": "data:image/png;base64,", "1": "data:image/png;base64,", "2": "data:image/png;base64,", "3": "data:image/png;base64,", "5": "data:image/png;base64,", "9": "data:image/png;base64,", "22": "data:image/png;base64,", "23": "data:image/png;base64,", "24": "data:image/png;base64,", "25": "data:image/png;base64,", "26": "data:image/png;base64,", "15": "data:image/png;base64,", "16": "data:image/png;base64,", "17": "data:image/png;base64,", "18": "data:image/png;base64,", "19": "data:image/png;base64,", "20": "data:image/png;base64,", "21": "data:image/png;base64,"}, "topics": [{"code": "UNITS", "title": "Metric Units & Electrical Quantities", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8009-2", "q": "Convert farads to microfarads by", "options": ["multiplying farads by 10⁶.", "multiplying picofarads by 10⁶.", "multiplying microfarads by 10⁶."], "correct": 0, "short": "multiplying farads by 10⁶.", "expl": "One farad equals 1,000,000 (10⁶) microfarads — a farad is a huge bucket, a microfarad a tiny one, so it takes a million tiny ones to fill it. Going farads → microfarads you multiply by 10⁶ (decimal 6 hops right).", "cite": "FAA-H-8083-30B, p. 12-50", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8009-3", "q": "Convert farads to picofarads by", "options": ["multiplying microfarads by 10⁻¹².", "multiplying farads by 10¹².", "multiplying picofarads by 10¹²."], "correct": 1, "short": "multiplying farads by 10¹².", "expl": "One farad equals 10¹² (a trillion) picofarads. To convert farads → picofarads you multiply by 10¹² — smaller bucket, many more of them.", "cite": "FAA-H-8083-30B, p. 12-51", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8009-4", "q": "How does an aviation mechanic convert picofarads to microfarads?", "options": ["Move the decimal 6 positions right.", "Move the decimal 3 positions left.", "Move the decimal 6 positions left."], "correct": 2, "short": "Move the decimal 6 positions left.", "expl": "Picofarad → microfarad climbs UP the ladder past nano (p → n → µ = 6 hops). Bigger unit means fewer of them, so move the decimal 6 places to the LEFT (÷10⁶).", "cite": "FAA-H-8083-30B, p. 12-4", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8020", "q": "The potential difference between two conductors which are insulated from each other is measured in", "options": ["volts.", "amperes.", "coulombs."], "correct": 0, "short": "volts.", "expl": "Potential difference is the electrical 'pressure' pushing between two points, and pressure (EMF/voltage) is measured in volts.", "cite": "FAA-H-8083-30B, p. 12-14", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8029-2", "q": "What does the letter Q symbolize when measuring electrical charge?", "options": ["Farad.", "Coulomb.", "Electron."], "correct": 1, "short": "Coulomb.", "expl": "Q is the symbol for quantity of electrical charge, and charge is measured in coulombs (one coulomb ≈ 6.28 × 10¹⁸ electrons). It ties into the capacitor formula C = Q/E.", "cite": "FAA-H-8083-30B, p. 12-16", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8030", "q": "Which term means .001 ampere?", "options": ["Microampere.", "Kiloampere.", "Milliampere."], "correct": 2, "short": "Milliampere.", "expl": "The prefix 'milli' means one-thousandth, so .001 ampere = 1 milliampere. (Micro = millionth, kilo = thousand — both wrong here.)", "cite": "FAA-H-8083-30B, p. 12-4", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8033", "q": ".002 kV equals", "options": ["2.0 volts.", "20 volts.", ".2 volt."], "correct": 0, "short": "2.0 volts.", "expl": "Kilo means 1,000, so .002 kV × 1,000 = 2.0 volts. Hop the decimal 3 places right for k → base unit.", "cite": "FAA-H-8083-30B, p. 12-4", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8037", "q": "What unit is used to express electrical power?", "options": ["Volt.", "Watt.", "Ampere."], "correct": 1, "short": "Watt.", "expl": "Electrical power — the rate of doing electrical work — is expressed in watts. (The volt is pressure, the ampere is flow; power P = E × I is watts.)", "cite": "FAA-H-8083-30B, p. 12-20", "topicName": "Metric Units & Electrical Quantities", "fig": null}, {"id": "8037-1", "q": "What is the basic unit of electrical quantity?", "options": ["Electromotive force.", "Ampere.", "Coulomb."], "correct": 2, "short": "Coulomb.", "expl": "The basic unit of electrical quantity (charge) is the coulomb. EMF and the ampere measure pressure and flow, not quantity of charge.", "cite": "FAA-H-8083-30B, p. 12-16", "topicName": "Metric Units & Electrical Quantities", "fig": null}]}, {"code": "OHM", "title": "Ohm's Law & Power", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8015", "q": "Which requires the most electrical power during operation? (Note: 1 horsepower = 746 watts)", "options": ["Two lights requiring 3 amperes each in a 24-volt parallel system.", "A 12-volt motor requiring 8 amperes.", "Four 30-watt lamps in a 12-volt parallel circuit."], "correct": 0, "short": "Two lights requiring 3 amperes each in a 24-volt parallel system.", "expl": "Power = E × I on each load. A: 12 V × 8 A = 96 W. B: four 30-W lamps = 120 W. C: two lights × 3 A × 24 V = 144 W. C draws the most.", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8016", "q": "How much power must a 24-volt generator furnish to a system which contains the following loads: one motor (75 percent efficient) rated 1/5 hp, three position lights of 20 watts each, one heating element drawing 5 amp, and one anticollision light drawing 3 amp? (Note: 1 horsepower = 746 watts)", "options": ["402 watts.", "450 watts.", "385 watts."], "correct": 1, "short": "450 watts.", "expl": "Add every load's watts. Motor: 1/5 hp = 149 W out ÷ 0.75 efficiency ≈ 199 W in. Three lights: 3 × 20 = 60 W. Heater: 5 A × 24 V = 120 W. Anticollision: 3 A × 24 V = 72 W. Total ≈ 451 ≈ 450 W.", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8017", "q": "A 12-volt electric motor has 1,000 watts input and 1 horsepower output. Maintaining the same efficiency, how much input power will a 24-volt, 1-horsepower electric motor require? (Note: 1 horsepower = 746 watts)", "options": ["2,000 watts.", "500 watts.", "1,000 watts."], "correct": 2, "short": "1,000 watts.", "expl": "Same horsepower output at the same efficiency means the same input power — 1,000 watts. Changing the voltage doesn't change the power needed for a given amount of work; it just changes the current.", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8018", "q": "How many amperes will a 28-volt generator be required to supply to a circuit containing five lamps in parallel, three of which have a resistance of 6 ohms each and two of which have a resistance of 5 ohms each?", "options": ["25.23 amperes.", "1.11 amperes.", "1 ampere."], "correct": 0, "short": "25.23 amperes.", "expl": "Each parallel lamp draws E/R. Three 6-Ω lamps: 3 × (28/6) = 14 A. Two 5-Ω lamps: 2 × (28/5) = 11.2 A. Total = 25.2 A (≈ 25.23) — parallel branch currents add.", "cite": "FAA-H-8083-30B, p. 12-41", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8019", "q": "A 24-volt, 1-horsepower DC electric motor that is 80 percent efficient requires 932.5 watts. How much power will a 12-volt, 1-horsepower DC electric motor that is 75 percent efficient require? (Note: 1 horsepower = 746 watts)", "options": ["932.5 watts.", "994.6 watts.", "1,305.5 watts."], "correct": 1, "short": "994.6 watts.", "expl": "One horsepower out = 746 W. At 75% efficiency the input is 746 ÷ 0.75 = 994.6 W. The voltage is a distractor — efficiency and output set the input power.", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8020-1", "q": "Which effect does not apply to the movement of electrons flowing in a conductor?", "options": ["Magnetic energy.", "Thermal energy.", "Static energy."], "correct": 2, "short": "Static energy.", "expl": "Electrons flowing in a conductor make a magnetic field around it and give off heat (thermal energy). Static energy is the odd one out — it belongs to charges sitting still, not to current flow.", "cite": "FAA-H-8083-30B, p. 12-12", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8023", "q": "(Refer to Figure 4.) How much power is being furnished to the circuit?", "options": ["2,645 watts.", "575 watts.", "2,875 watts."], "correct": 0, "short": "2,645 watts.", "expl": "Real (true) power dissipated by the resistor in Figure 4 = I² × R = 23² × 5 = 529 × 5 = 2,645 watts. Use the current and resistance shown, not just volt-amps.", "cite": "FAA-H-8083-30B, p. 12-64", "topicName": "Ohm's Law & Power", "fig": "4"}, {"id": "8032", "q": "A 14-ohm resistor is to be installed in a series circuit carrying .05 ampere. How much power will the resistor be required to dissipate?", "options": ["At least .70 milliwatt.", "At least 35 milliwatts.", "Less than .035 watt."], "correct": 1, "short": "At least 35 milliwatts.", "expl": "Power a resistor dissipates = I² × R = (.05)² × 14 = .0025 × 14 = .035 W = 35 milliwatts, so it must be rated for at least that.", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8036", "q": "Which requires the most electrical power? (Note: 1 horsepower = 746 watts)", "options": ["Four 30-watt lamps arranged in a 12-volt parallel circuit.", "A 24-volt anticollision light circuit consisting of two light assemblies which require 3 amperes each during operation.", "A 1/5-horsepower, 24-volt motor which is 75 percent efficient."], "correct": 2, "short": "A 1/5-horsepower, 24-volt motor which is 75 percent efficient.", "expl": "Convert each to watts. A: (0.2 hp × 746) ÷ 0.75 = 199 W. B: four 30-W lamps = 120 W. C: two loads × 3 A × 24 V = 144 W. The 1/5-hp motor (A) needs the most.", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}, {"id": "8038", "q": "What is the operating resistance of a 30-watt light bulb designed for a 28-volt system?", "options": ["26 ohms.", "1.07 ohms.", "0.93 ohm."], "correct": 0, "short": "26 ohms.", "expl": "Operating resistance from watts and volts: R = E²/P = 28² ÷ 30 = 784 ÷ 30 ≈ 26 Ω. (This is the R_t = E²/P relationship in Figure 64.)", "cite": "FAA-H-8083-30B, p. 12-21", "topicName": "Ohm's Law & Power", "fig": null}]}, {"code": "CIRC", "title": "Circuits & Resistance (Series/Parallel/Complex)", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8021", "q": "A 24-volt source is required to furnish 48 watts to a parallel circuit consisting of four resistors of equal value. What is the voltage drop across each resistor?", "options": ["24 volts.", "12 volts.", "6 volts."], "correct": 0, "short": "24 volts.", "expl": "In a parallel circuit every branch sees the full source voltage. All four resistors are across the 24-V source, so the drop across each one is 24 volts.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8025", "q": "(Refer to Figure 6.) If resistor R 5 is disconnected at the junction of R 4 and R3 as shown, what will the ohmmeter read?", "options": ["2.76 ohms.", "3 ohms.", "12 ohms."], "correct": 1, "short": "3 ohms.", "expl": "With the R5 leg lifted at the R4–R3 junction, the ohmmeter looks back into two equal 6-Ω branches in parallel: 6 × 6 ÷ (6 + 6) = 3 Ω. Trace the break shown in Figure 6.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "6"}, {"id": "8026", "q": "(Refer to Figure 7.) If resistor R 3 is disconnected at terminal D, what will the ohmmeter read?", "options": ["10 ohms.", "20 ohms.", "Infinite resistance."], "correct": 2, "short": "Infinite resistance.", "expl": "Disconnecting R3 at terminal D opens the only path back to the meter, so the circuit is broken — the ohmmeter reads infinite resistance (an open reads OL / no continuity).", "cite": "FAA-H-8083-30B, p. 12-82", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "7"}, {"id": "8027", "q": "(Refer to Figure 8.) With an ohmmeter connected into the circuit as shown, what will the ohmmeter read?", "options": ["10 ohms.", "20 ohms.", "Infinite resistance."], "correct": 0, "short": "10 ohms.", "expl": "As the meter is connected in Figure 8 it looks across two 20-Ω resistors in parallel: 20 × 20 ÷ (20 + 20) = 10 Ω.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "8"}, {"id": "8031", "q": "A cabin entry light of 10 watts and a dome light of 20 watts are connected in parallel to a 30-volt source. If the voltage across the 10-watt light is measured, it will be", "options": ["half the voltage across the 20-watt light.", "equal to the voltage across the 20-watt light.", "one-third of the input voltage."], "correct": 1, "short": "equal to the voltage across the 20-watt light.", "expl": "Both lamps are wired in parallel across the same 30-V source, so each one has the full source voltage across it — the 10-W lamp's voltage equals the 20-W lamp's voltage.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8034", "q": "(Refer to Figure 10.) What is the measured voltage of the series-parallel circuit between terminals A and B?", "options": ["1.5 volts.", "4.5 volts.", "3.0 volts."], "correct": 2, "short": "3.0 volts.", "expl": "Read the series-parallel network in Figure 10: between A and B the meter measures the drop across the parallel section, which works out to 3.0 volts. Combine the parallel branches first, then apply the divider.", "cite": "FAA-H-8083-30B, p. 12-42", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "10"}, {"id": "8035", "q": "(Refer to Figure 64.) A 24-volt source is required to furnish 48 watts to a parallel circuit consisting of two resistors of equal value. What is the value of each resistor?", "options": ["24 ohms.", "12 ohms.", "6 ohms."], "correct": 0, "short": "24 ohms.", "expl": "Total resistance from R_t = E²/P (Figure 64) = 24² ÷ 48 = 12 Ω. Two equal resistors in parallel give 12 Ω only if each one is twice that — 24 Ω apiece.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "64"}, {"id": "8039", "q": "When referencing resistance in a parallel DC circuit, which of the following statements is true?", "options": ["The current is equal in all portions of the circuit.", "The total current is equal to the sum of the currents through the individual branches of the circuit.", "The current in amperes can be found by dividing the source voltage in volts by the sum of the resistors in ohms."], "correct": 1, "short": "The total current is equal to the sum of the currents through the individual branches of the circuit.", "expl": "In a parallel DC circuit the total (line) current equals the SUM of the currents through the individual branches — Kirchhoff's current law. The current is not equal everywhere (that's series).", "cite": "FAA-H-8083-30B, p. 12-41", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8042", "q": "If three resistors of 3 ohms, 5 ohms, and 22 ohms are connected in series in a 28-volt circuit, how much current will flow through the 3-ohm resistor?", "options": ["9.3 amperes.", "1.05 amperes.", "0.93 ampere."], "correct": 2, "short": "0.93 ampere.", "expl": "Series resistors add: 3 + 5 + 22 = 30 Ω total. Current is the same everywhere in a series loop: I = E/R = 28 ÷ 30 = 0.93 A.", "cite": "FAA-H-8083-30B, p. 12-35", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8043", "q": "A circuit has an applied voltage of 30 volts and a load consisting of a 10-ohm resistor in series with a 20-ohm resistor. What is the voltage drop across the 10-ohm resistor?", "options": ["10 volts.", "20 volts.", "30 volts."], "correct": 0, "short": "10 volts.", "expl": "Series divider: total R = 10 + 20 = 30 Ω, so I = 30 V ÷ 30 Ω = 1 A. Drop across the 10-Ω resistor = I × R = 1 × 10 = 10 volts.", "cite": "FAA-H-8083-30B, p. 12-35", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8044", "q": "(Refer to Figure 11.) Find the total current flowing n the wire between points C and D.", "options": ["6.0 amperes.", "3.0 amperes.", "2.4 amperes."], "correct": 1, "short": "3.0 amperes.", "expl": "In Figure 11 the wire between C and D carries the total (main-line) current feeding the network. Working the series-parallel combination gives a total current of 3.0 amperes.", "cite": "FAA-H-8083-30B, p. 12-42", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "11"}, {"id": "8044-1", "q": "(Refer to Figure 11.) What happens to the current in the circuit if all the resistors double in value?", "options": ["The current doubles.", "The current remains the same.", "The current is cut in half."], "correct": 2, "short": "The current is cut in half.", "expl": "Current = E/R. If every resistor doubles, the total resistance doubles, so for the same battery voltage the current is cut in half — Ohm's law, straight up.", "cite": "FAA-H-8083-30B, p. 12-17", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "11"}, {"id": "8045", "q": "(Refer to Figure 11.) Find the voltage across the 8-ohm resistor.", "options": ["24 volts.", "8 volts.", "20.4 volts."], "correct": 0, "short": "24 volts.", "expl": "The 8-Ω resistor (R1) is wired directly across the 24-V battery in Figure 11, so it sees the full source — 24 volts. Voltage across a component in parallel with the source equals the source.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "11"}, {"id": "8045-1", "q": "In a parallel circuit with four 6-ohm resistors across a 24-volt battery, what is the total voltage across resistor-three (VR3) in the circuit?", "options": ["6 volts.", "24 volts.", "18 volts."], "correct": 1, "short": "24 volts.", "expl": "Parallel again — all four 6-Ω resistors sit across the same 24-V battery, so the voltage across R3 (and every other one) is the full 24 volts.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8046", "q": "(Refer to Figure 12.) Find the total resistance of the circuit.", "options": ["16 ohms.", "2.6 ohms.", "21.2 ohms."], "correct": 2, "short": "21.2 ohms.", "expl": "Reduce Figure 12 in stages: combine the parallel legs, then add the series parts. The combination totals 21.2 Ω. (The R_a/R_b/R_c ladder shown is the step-by-step method.)", "cite": "FAA-H-8083-30B, p. 12-42", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "12"}, {"id": "8047", "q": "Which is correct in reference to electrical resistance?", "options": ["If one of three bulbs in a parallel lighting circuit is removed, the total resistance of the circuit will become greater.", "Two electrical devices will have the same combined resistance if they are connected in series as they will have if connected in parallel.", "An electrical device that has a high resistance will use more power than one with a low resistance with the same applied voltage."], "correct": 0, "short": "If one of three bulbs in a parallel lighting circuit is removed, the total resistance of the circuit will become greater.", "expl": "In a parallel circuit, every extra path lowers total resistance; remove a path (one bulb) and the total resistance goes UP. Fewer parallel branches = higher total R.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8049", "q": "(Refer to Figure 13.) Determine the total current flow in the circuit.", "options": ["0.2 ampere.", "1.4 amperes.", "0.8 ampere."], "correct": 1, "short": "1.4 amperes.", "expl": "Total current is the sum of the parallel branch currents (Figure 13): 12 V across 30 Ω, 60 Ω, and 15 Ω gives 0.4 + 0.2 + 0.8 = 1.4 A.", "cite": "FAA-H-8083-30B, p. 12-41", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "13"}, {"id": "8049-1", "q": "In a parallel circuit with three 6-ohm resistors across a 12-volt battery, what is the total current (It) value in the circuit?", "options": ["2 amps.", "12 amps.", "6 amps."], "correct": 2, "short": "6 amps.", "expl": "Three 6-Ω resistors in parallel across 12 V: each draws 12 ÷ 6 = 2 A, and the branch currents add to 3 × 2 = 6 A total.", "cite": "FAA-H-8083-30B, p. 12-41", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8050", "q": "(Refer to Figure 14.) The total resistance of the circuit is", "options": ["17 ohms.", "25 ohms.", "35 ohms."], "correct": 0, "short": "17 ohms.", "expl": "Work Figure 14 inside-out: combine the parallel resistors first, then add the series pieces. The total resistance comes to 17 Ω.", "cite": "FAA-H-8083-30B, p. 12-42", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "14"}, {"id": "8051", "q": "Which of these will cause the resistance of a conductor to decrease?", "options": ["Decrease the length or the cross-sectional area.", "Decrease the length or increase the cross-sectional area.", "Increase the length or decrease the cross-sectional area."], "correct": 1, "short": "Decrease the length or increase the cross-sectional area.", "expl": "Resistance rises with length and falls with cross-sectional area. To make resistance go DOWN, shorten the conductor or fatten it (more area) — a wider, shorter pipe flows easier.", "cite": "FAA-H-8083-30B, p. 12-18", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8053", "q": "(Refer to Figure 64.) A 48-volt source is required to furnish 192 watts to a parallel circuit consisting of three resistors of equal value. What is the value of each resistor?", "options": ["4 ohms.", "12 ohms.", "36 ohms."], "correct": 2, "short": "36 ohms.", "expl": "R_t = E²/P (Figure 64) = 48² ÷ 192 = 12 Ω total. Three equal resistors in parallel equal 12 Ω only if each is 3 × 12 = 36 Ω.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": "64"}, {"id": "8054", "q": "Which is correct concerning a parallel circuit?", "options": ["Total resistance will be smaller than the smallest resistor.", "Total resistance will decrease when one of the resistances is removed.", "Total voltage drop is the same as the total resistance."], "correct": 0, "short": "Total resistance will be smaller than the smallest resistor.", "expl": "The total resistance of a parallel circuit is always smaller than the smallest single resistor — adding paths gives current more ways to flow, which lowers overall resistance.", "cite": "FAA-H-8083-30B, p. 12-40", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}, {"id": "8055", "q": "The voltage drop in a circuit of known resistance is dependent on", "options": ["the voltage of the circuit.", "the amperage of the circuit.", "only the resistance of the conductor and does not change with a change in either voltage or amperage."], "correct": 1, "short": "the amperage of the circuit.", "expl": "For a fixed resistance, the voltage drop E = I × R rides on the current through it — change the amperage and the drop changes with it.", "cite": "FAA-H-8083-30B, p. 12-35", "topicName": "Circuits & Resistance (Series/Parallel/Complex)", "fig": null}]}, {"code": "CAP", "title": "Capacitance", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8001", "q": "The working voltage of a capacitor in an AC circuit should be", "options": ["at least 50 percent greater than the highest applied voltage.", "equal to the highest applied voltage.", "at least 20 percent greater than the highest applied voltage."], "correct": 0, "short": "at least 50 percent greater than the highest applied voltage.", "expl": "The working voltage is the most a capacitor's dielectric can take before it breaks down. AC swings to a peak that is higher than the RMS value you read on a meter, so you build in margin — the working voltage should be at least 50% greater than the highest applied voltage.", "cite": "FAA-H-8083-30B, p. 12-51", "topicName": "Capacitance", "fig": null}, {"id": "8002-2", "q": "Electrostatic fields are also known as", "options": ["electrostatic fields.", "dielectric fields.", "static fields."], "correct": 1, "short": "dielectric fields.", "expl": "The electrostatic field that stores energy between two charged plates is also called the dielectric field — 'dielectric' names the insulating material the field lives in.", "cite": "FAA-H-8083-30B, p. 12-50", "topicName": "Capacitance", "fig": null}, {"id": "8006", "q": "(Refer to Figure 1.) When different rated capacitors are connected in series in a circuit, the total capacitance is", "options": ["greater than the capacitance of the highest rated capacitor.", "equal to the sum of all the capacitances.", "less than the capacitance of the lowest rated capacitor."], "correct": 2, "short": "less than the capacitance of the lowest rated capacitor.", "expl": "Capacitors in series stack their dielectric gaps end-to-end, so the total capacitance drops below even the smallest one in the string — the same reciprocal math shape (1/C_T = 1/C1 + 1/C2 + …) that resistors follow in parallel.", "cite": "FAA-H-8083-30B, p. 12-53", "topicName": "Capacitance", "fig": "1"}, {"id": "8006-1", "q": "Capacitors are sometimes used in DC circuits to", "options": ["smooth out slight pulsations in current/voltage.", "counteract inductive reactance at specific locations.", "assist in stepping voltage and current up and/or down."], "correct": 0, "short": "smooth out slight pulsations in current/voltage.", "expl": "Think of a capacitor as a small surge tank or balloon tied across the line: it soaks up electrons when the voltage rises and dumps them back when it sags. In a DC circuit that action smooths out slight pulsations (ripple) in current/voltage.", "cite": "FAA-H-8083-30B, p. 12-50", "topicName": "Capacitance", "fig": null}, {"id": "8008", "q": "The amount of electricity a capacitor can store is directly proportional to the", "options": ["distance between the plates and inversely proportional to the plate area.", "plate area and inversely proportional to the distance between the plates.", "plate area and is not affected by the distance between the plates."], "correct": 1, "short": "plate area and inversely proportional to the distance between the plates.", "expl": "Two things set how much charge a capacitor holds: plate area (more area = more storage, directly proportional) and plate spacing (closer plates = stronger field = more storage, so it's inversely proportional to the distance between the plates).", "cite": "FAA-H-8083-30B, p. 12-51", "topicName": "Capacitance", "fig": null}, {"id": "8009", "q": "(Refer to Figure 2.) What is the total capacitance of a certain circuit containing three capacitors with capacitances of .02 microfarad, .05 microfarad, and .10 microfarad, respectively?", "options": [".170 µF.", "0.125 pF.", ".0125 µF."], "correct": 2, "short": ".0125 µF.", "expl": "Series capacitors use the reciprocal formula: 1/C_T = 1/.02 + 1/.05 + 1/.10 = 50 + 20 + 10 = 80, so C_T = 1/80 = .0125 µF. Trace the drawn series string in Figure 2 above.", "cite": "FAA-H-8083-30B, p. 12-53", "topicName": "Capacitance", "fig": "2"}, {"id": "8009-1", "q": "What is the total capacitance of a circuit containing three capacitors in parallel with capacitances of .02 microfarad, .05 microfarad, and .10 microfarad, respectively?", "options": [".170 µF.", "0.125 µF.", ".0125 µF."], "correct": 0, "short": ".170 µF.", "expl": "Capacitors in parallel simply add — their plate areas combine: C_T = C1 + C2 + C3 = .02 + .05 + .10 = .170 µF.", "cite": "FAA-H-8083-30B, p. 12-54", "topicName": "Capacitance", "fig": null}, {"id": "8011", "q": "When different rated capacitors are connected in parallel in a circuit, the total capacitance is (Note: CT = C1 + C2 + C3 . . .)", "options": ["less than the capacitance of the lowest rated capacitor.", "equal to the sum of all the capacitances.", "equal to the capacitance of the highest rated capacitor."], "correct": 1, "short": "equal to the sum of all the capacitances.", "expl": "In parallel the plate areas add together, so total capacitance is the straight sum of all the individual values (C_T = C1 + C2 + C3 …) — it grows, unlike the series case.", "cite": "FAA-H-8083-30B, p. 12-54", "topicName": "Capacitance", "fig": null}, {"id": "8014", "q": "What is the total capacitance of a certain circuit containing three capacitors with capacitances of .25 microfarad, .03 microfarad, and .12 microfarad, respectively? (Note: CT = C1 + C2 + C3)", "options": [".04 pF.", ".04 µF.", ".4 µF."], "correct": 2, "short": ".4 µF.", "expl": "The note tells you these are in parallel (C_T = C1 + C2 + C3), so just add: .25 + .03 + .12 = .40 µF.", "cite": "FAA-H-8083-30B, p. 12-54", "topicName": "Capacitance", "fig": null}]}, {"code": "IND", "title": "Inductance, Reactance & Impedance", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8002", "q": "The term that describes the combined resistive forces in an AC circuit is", "options": ["impedance.", "resistance.", "reactance."], "correct": 0, "short": "impedance.", "expl": "Impedance (Z) is the total opposition to current in an AC circuit — resistance and reactance combined into one figure (Z = √(R² + X²)).", "cite": "FAA-H-8083-30B, p. 12-59", "topicName": "Inductance, Reactance & Impedance", "fig": null}, {"id": "8002-1", "q": "What is the opposition to the flow of AC produced by an electromagnetic field (EMF) with generated back voltage called?", "options": ["Capacitive reactance.", "Inductive reactance.", "Mutual inductance."], "correct": 1, "short": "Inductive reactance.", "expl": "A coil fights a change in current by generating a back-EMF (counter-voltage). That opposition is inductive reactance, X_L, measured in ohms just like resistance.", "cite": "FAA-H-8083-30B, p. 12-58", "topicName": "Inductance, Reactance & Impedance", "fig": null}, {"id": "8004", "q": "The opposition offered by a coil to the flow of alternating current (ignoring resistance) is called", "options": ["impedance.", "reluctance.", "inductive reactance."], "correct": 2, "short": "inductive reactance.", "expl": "The opposition a coil offers to AC (setting aside its wire resistance) is inductive reactance. Impedance is the total, reluctance is a magnetic term — only inductive reactance fits.", "cite": "FAA-H-8083-30B, p. 12-58", "topicName": "Inductance, Reactance & Impedance", "fig": null}, {"id": "8005", "q": "An increase in which of the following factors will cause an increase in the inductive reactance of a circuit?", "options": ["Inductance and frequency.", "Resistance and voltage.", "Resistance and capacitive reactance."], "correct": 0, "short": "Inductance and frequency.", "expl": "Inductive reactance X_L = 2πfL — it climbs when either the frequency (f) or the inductance (L) goes up. Resistance, voltage, and capacitive reactance don't affect X_L.", "cite": "FAA-H-8083-30B, p. 12-58", "topicName": "Inductance, Reactance & Impedance", "fig": null}, {"id": "8012", "q": "When inductors are connected in series in a circuit, the total inductance (where the magnetic fields of each inductor do not affect the others) is (Note: LT = L1 + L2 + L3 . . .)", "options": ["less than the inductance of the lowest rated inductor.", "equal to the sum of the individual inductances.", "equal to the inductance of the highest rated inductor."], "correct": 1, "short": "equal to the sum of the individual inductances.", "expl": "Inductors in series, with no magnetic coupling between them, add just like series resistors: L_T = L1 + L2 + L3 …", "cite": "FAA-H-8083-30B, p. 12-58", "topicName": "Inductance, Reactance & Impedance", "fig": null}, {"id": "8013", "q": "(Refer to Figure 3.) When more than two inductors of different inductances are connected in parallel in a circuit, the total inductance is", "options": ["equal to the inductance of the highest rated inductor.", "equal to the sum of the individual inductances.", "less than the inductance of the lowest rated inductor."], "correct": 2, "short": "less than the inductance of the lowest rated inductor.", "expl": "Inductors in parallel combine like resistors in parallel — the total is LESS than the smallest inductor in the group (reciprocal formula). Trace the parallel string in Figure 3.", "cite": "FAA-H-8083-30B, p. 12-58", "topicName": "Inductance, Reactance & Impedance", "fig": "3"}, {"id": "8024", "q": "(Refer to Figure 5.) What is the impedance of an AC-series circuit consisting of an inductor with a reactance of 10 ohms, a capacitor with a reactance of 4 ohms, and a resistor with a resistance of 8 ohms?", "options": ["10 ohms.", "22 ohms.", "5.29 ohms."], "correct": 0, "short": "10 ohms.", "expl": "Impedance Z = √(R² + (X_L − X_C)²) (Figure 5). Net reactance = 10 − 4 = 6 Ω, so Z = √(8² + 6²) = √(64 + 36) = √100 = 10 Ω. Inductive and capacitive reactance partly cancel.", "cite": "FAA-H-8083-30B, p. 12-60", "topicName": "Inductance, Reactance & Impedance", "fig": "5"}, {"id": "8041", "q": "Transfer of electric energy from one circuit to another without the aid of electrical connections", "options": ["is called capacitance.", "is called induction.", "can cause excessive arcing and heat, and as a result is practical for use only with low voltages/amperages."], "correct": 1, "short": "is called induction.", "expl": "Moving electrical energy from one circuit to another with no wires touching between them is called induction — a changing magnetic field crossing the second coil. It's the whole basis of the transformer.", "cite": "FAA-H-8083-30B, p. 12-56", "topicName": "Inductance, Reactance & Impedance", "fig": null}]}, {"code": "AC", "title": "AC Theory (Effective/RMS Values)", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8007", "q": "In an AC circuit, the effective voltage is", "options": ["less than the maximum instantaneous voltage.", "equal to the maximum instantaneous voltage.", "greater than the maximum instantaneous voltage."], "correct": 0, "short": "less than the maximum instantaneous voltage.", "expl": "Effective (RMS) voltage = 0.707 × peak, so it is LESS than the maximum instantaneous (peak) voltage. Effective is the working value your AC voltmeter reads.", "cite": "FAA-H-8083-30B, p. 12-49", "topicName": "AC Theory (Effective/RMS Values)", "fig": null}, {"id": "8010", "q": "Unless otherwise specified, any values given for current or voltage in an AC circuit are assumed to be", "options": ["instantaneous values.", "effective values.", "maximum values."], "correct": 1, "short": "effective values.", "expl": "Unless a problem says otherwise, AC current/voltage figures are effective (RMS) values — 0.707 of peak — because that's what meters read and what ratings are based on.", "cite": "FAA-H-8083-30B, p. 12-49", "topicName": "AC Theory (Effective/RMS Values)", "fig": null}, {"id": "8022", "q": "When calculating power in a reactive or inductive AC circuit, the true power is", "options": ["more than the apparent power.", "less than the apparent power in a reactive circuit and more than the apparent power in an inductive circuit.", "less than the apparent power."], "correct": 2, "short": "less than the apparent power.", "expl": "True power (real watts that do work) is always less than apparent power (volt-amps) in a reactive or inductive AC circuit. The gap is reactive power that sloshes back and forth without doing work.", "cite": "FAA-H-8083-30B, p. 12-64", "topicName": "AC Theory (Effective/RMS Values)", "fig": null}]}, {"code": "MAG", "title": "Magnetism & Transformers", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8003", "q": "The basis for transformer operation in the use of alternating current is mutual", "options": ["inductance.", "capacitance.", "reactance."], "correct": 0, "short": "inductance.", "expl": "A transformer works on MUTUAL inductance — the changing field of the primary coil inducing a voltage in the secondary. No moving parts, just linked magnetic fields, which is why it only works on AC.", "cite": "FAA-H-8083-30B, p. 12-65", "topicName": "Magnetism & Transformers", "fig": null}, {"id": "8004-1", "q": "What factors strengthen a coil inductor?", "options": ["Limiting and separating the coils.", "Adding coils close together.", "Adding and separating the coils."], "correct": 1, "short": "Adding coils close together.", "expl": "Packing more turns close together concentrates the magnetic field of a coil, building a stronger electromagnet. Spreading or limiting the loops weakens it.", "cite": "FAA-H-8083-30B, p. 12-57", "topicName": "Magnetism & Transformers", "fig": null}, {"id": "8048", "q": "What happens to the current in a voltage step-up transformer with a ratio of 1 to 4?", "options": ["The current is stepped up by a 1 to 4 ratio.", "The current does not change.", "The current is stepped down by a 1 to 4 ratio."], "correct": 2, "short": "The current is stepped down by a 1 to 4 ratio.", "expl": "Power in ≈ power out in a transformer, so voltage and current trade off inversely. A 1:4 voltage step-UP means the current is stepped DOWN by 1:4 (raise volts, lower amps).", "cite": "FAA-H-8083-30B, p. 12-67", "topicName": "Magnetism & Transformers", "fig": null}, {"id": "8052", "q": "Through which material will magnetic lines of force pass the most readily?", "options": ["Iron.", "Copper.", "Aluminum."], "correct": 0, "short": "Iron.", "expl": "Permeability measures how easily magnetic lines of force pass through a material. Of copper, iron, and aluminum, IRON has by far the highest permeability, so the lines travel through it most readily.", "cite": "FAA-H-8083-30B, p. 12-12", "topicName": "Magnetism & Transformers", "fig": null}]}, {"code": "METER", "title": "Meters & Measurement", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8028", "q": "(Refer to Figure 9.) How many instruments (voltmeters and ammeters) are installed correctly?", "options": ["Two.", "Three.", "One."], "correct": 0, "short": "Two.", "expl": "Count the correctly wired meters in Figure 9: a voltmeter belongs in parallel across a load and an ammeter in series with it. Two of the instruments shown are installed correctly.", "cite": "FAA-H-8083-30B, p. 12-71", "topicName": "Meters & Measurement", "fig": "9"}, {"id": "8029", "q": "The correct way to connect a test voltmeter in a circuit is", "options": ["in series with a unit.", "in parallel with a unit.", "between the source voltage and the load."], "correct": 1, "short": "in parallel with a unit.", "expl": "A voltmeter reads the voltage difference across a component, so it is connected in PARALLEL with (across) the unit — never in series, which would starve the circuit.", "cite": "FAA-H-8083-30B, p. 12-71", "topicName": "Meters & Measurement", "fig": null}, {"id": "8029-1", "q": "What will a voltmeter read if properly connected across a closed switch in a circuit with electrical power on?", "options": ["Voltage drop in the component(s) the switch is connected to.", "System voltage.", "Zero voltage."], "correct": 2, "short": "Zero voltage.", "expl": "A good, closed switch has essentially no voltage drop across it, so a voltmeter placed across it reads ZERO. (If it read system voltage, the switch would be open/faulty.)", "cite": "FAA-H-8083-30B, p. 12-82", "topicName": "Meters & Measurement", "fig": null}]}, {"code": "SEMI", "title": "Semiconductors & Logic Gates", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8039-1", "q": "Which of the following is commonly used as a rectifier in electrical circuits?", "options": ["Diodes.", "Diodes and anodes.", "Diodes and cathodes."], "correct": 0, "short": "Diodes.", "expl": "A diode passes current one direction and blocks the other, which is exactly what a rectifier does — so diodes are the common rectifier in electrical circuits.", "cite": "FAA-H-8083-30B, p. 12-100", "topicName": "Semiconductors & Logic Gates", "fig": null}, {"id": "8040", "q": "Diodes are used in electrical power supply circuits primarily as", "options": ["switches.", "rectifiers.", "relays."], "correct": 1, "short": "rectifiers.", "expl": "In a power-supply circuit, diodes act as rectifiers, turning AC into pulsating DC. (They aren't switches or relays.)", "cite": "FAA-H-8083-30B, p. 12-100", "topicName": "Semiconductors & Logic Gates", "fig": null}, {"id": "8075", "q": "In a P-N-P transistor application, the solid-state device is turned on when the", "options": ["base is positive with respect to the emitter.", "emitter is negative with respect to the base.", "base is negative with respect to the emitter."], "correct": 2, "short": "base is negative with respect to the emitter.", "expl": "A P-N-P transistor turns ON when its base is NEGATIVE with respect to the emitter — that forward-biases the emitter-base junction and lets collector current flow.", "cite": "FAA-H-8083-30B, p. 12-107", "topicName": "Semiconductors & Logic Gates", "fig": null}, {"id": "8076", "q": "In an N-P-N transistor application, the solid-state device is turned on when the", "options": ["base is positive with respect to the emitter.", "emitter is positive with respect to the base.", "base is negative with respect to the emitter."], "correct": 0, "short": "base is positive with respect to the emitter.", "expl": "An N-P-N transistor turns ON when its base is POSITIVE with respect to the emitter (forward bias). It's the mirror image of the P-N-P rule.", "cite": "FAA-H-8083-30B, p. 12-106", "topicName": "Semiconductors & Logic Gates", "fig": null}, {"id": "8077", "q": "Typical application for zener diodes is as", "options": ["full-wave rectifiers.", "voltage regulators.", "half-wave rectifiers."], "correct": 1, "short": "voltage regulators.", "expl": "Zener diodes are run in reverse breakdown, where they hold a steady voltage. That makes their typical job voltage regulation, not rectifying.", "cite": "FAA-H-8083-30B, p. 12-103", "topicName": "Semiconductors & Logic Gates", "fig": null}, {"id": "8078", "q": "(Refer to Figure 22.) Which illustration is correct concerning bias application and current (positive charge) flow?", "options": ["2.", "3.", "1."], "correct": 2, "short": "1.", "expl": "Illustration 1 shows correct bias: on the N-P-N the base is positive to the emitter (forward-biased emitter-base junction), so base current — and therefore collector current — flows. Trace the current-flow arrow in Figure 22.", "cite": "FAA-H-8083-30B, p. 12-107", "topicName": "Semiconductors & Logic Gates", "fig": "22"}, {"id": "8079", "q": "Forward biasing of a solid-state device will cause the device to", "options": ["conduct.", "conduct via zener breakdown.", "turn off."], "correct": 0, "short": "conduct.", "expl": "Forward biasing a solid-state junction turns it ON — it conducts. (Reverse bias blocks; zener breakdown is a special reverse case, not forward.)", "cite": "FAA-H-8083-30B, p. 12-98", "topicName": "Semiconductors & Logic Gates", "fig": null}, {"id": "8080", "q": "(Refer to Figure 23.) If an open occurs at R1, the light", "options": ["cannot be turned on.", "cannot be turned off.", "will not be affected."], "correct": 1, "short": "cannot be turned off.", "expl": "In Figure 23 an open at R1 removes the path that turns the transistor OFF, so the light cannot be turned off — it stays on.", "cite": "FAA-H-8083-30B, p. 12-107", "topicName": "Semiconductors & Logic Gates", "fig": "23"}, {"id": "8081", "q": "(Refer to Figure 23.) If R 2 sticks in the up position, the light will", "options": ["be very dim.", "not illuminate.", "be on full bright."], "correct": 2, "short": "be on full bright.", "expl": "If R2 sticks in the up position (Figure 23) the base gets full drive, the transistor saturates, and the light burns full bright.", "cite": "FAA-H-8083-30B, p. 12-107", "topicName": "Semiconductors & Logic Gates", "fig": "23"}, {"id": "8082", "q": "(Refer to Figure 24.) Which statement concerning the depicted logic gate is true?", "options": ["Any input being 1 will produce a 1 output.", "Any input being 1 will produce a 0 output.", "All inputs must be 1 to produce a 1 output."], "correct": 0, "short": "Any input being 1 will produce a 1 output.", "expl": "The gate in Figure 24 is an OR gate: ANY input being 1 produces a 1 output. Only all-zeros gives a 0.", "cite": "FAA-H-8083-30B, p. 12-122", "topicName": "Semiconductors & Logic Gates", "fig": "24"}, {"id": "8083", "q": "(Refer to Figure 25.) In a functional and operating circuit, the depicted logic gate’s output will be 0", "options": ["only when all inputs are 0.", "when one or more inputs are 0.", "when all inputs are 1."], "correct": 1, "short": "when one or more inputs are 0.", "expl": "The gate in Figure 25 is an AND gate: the output is 1 only when ALL inputs are 1, so it goes to 0 when one or more inputs are 0.", "cite": "FAA-H-8083-30B, p. 12-121", "topicName": "Semiconductors & Logic Gates", "fig": "25"}, {"id": "8084", "q": "(Refer to Figure 26.) Which of the logic gate output conditions is correct with respect to the given inputs?", "options": ["1.", "3.", "2."], "correct": 2, "short": "2.", "expl": "The Exclusive-OR gate in Figure 26 outputs 1 only when the inputs DIFFER. Illustration 2 (inputs 1 and 0 → output 1) is the correct condition.", "cite": "FAA-H-8083-30B, p. 12-122", "topicName": "Semiconductors & Logic Gates", "fig": "26"}, {"id": "8084-1", "q": "Which of the following logic gates will provide an active high out only when all inputs are different?", "options": ["XOR.", "XNOR.", "NAND."], "correct": 0, "short": "XOR.", "expl": "A gate that goes high only when all inputs are different is the Exclusive-OR (XOR). NAND and XNOR don't follow the 'all-different' rule.", "cite": "FAA-H-8083-30B, p. 12-122", "topicName": "Semiconductors & Logic Gates", "fig": null}]}, {"code": "PROT", "title": "Circuit Protection & Motors", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8056", "q": "A thermal switch, or thermal protector, as used in an electric motor, is designed to", "options": ["open the circuit in order to allow cooling of the motor.", "close the integral fan circuit to allow cooling of the motor.", "reroute the circuit to ground."], "correct": 0, "short": "open the circuit in order to allow cooling of the motor.", "expl": "A thermal switch/protector in a motor OPENS the circuit when the motor overheats, shutting it down so it can cool before it resets and runs again.", "cite": "FAA-H-8083-30B, p. 12-29", "topicName": "Circuit Protection & Motors", "fig": null}, {"id": "8597", "q": "What schematic symbol represents a current limiter?", "options": ["A triangle and a Z-like symbol across a horizontal line.", "Two triangles pointing to each other with a line on both sides of the triangles.", "One triangle pointing to a vertical line."], "correct": 1, "short": "Two triangles pointing to each other with a line on both sides of the triangles.", "expl": "The current-limiter schematic symbol is two triangles pointing toward each other with a line on both sides. (A single triangle to a line is a diode; a triangle plus Z is a zener.) See the symbol chart, Fig. 4-29, p. 4-24.", "cite": "FAA-H-8083-30B, p. 12-29", "topicName": "Circuit Protection & Motors", "fig": null}, {"id": "8597-1", "q": "What kind of circuit protection device can be reset?", "options": ["Fuse.", "Current limiter.", "Circuit breaker."], "correct": 2, "short": "Circuit breaker.", "expl": "A circuit breaker can be RESET after it trips; a fuse or current limiter is one-shot and must be replaced. So the resettable protection device is the circuit breaker.", "cite": "FAA-H-8083-30B, p. 12-29", "topicName": "Circuit Protection & Motors", "fig": null}]}, {"code": "BATT", "title": "Batteries — Lead-Acid & Ni-Cad", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8045-2", "q": "If each cell, connected in series, equals 2 volts, how would a 12-cell lead acid battery be rated?", "options": ["24 volts.", "12 volts.", "6 volts."], "correct": 0, "short": "24 volts.", "expl": "Cells in series add their voltages: 12 cells × 2 volts each = 24 volts. (Series adds volts; capacity/ampere-hours stays the same.)", "cite": "FAA-H-8083-30B, p. 12-87", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8085", "q": "A lead-acid battery with 12 cells connected in series (no-load voltage = 2.1 volts per cell) furnishes 10 amperes to a load of 2-ohms resistance. The internal resistance of the battery in this instance is", "options": ["2.52 ohms.", "0.52 ohm.", "5.0 ohms."], "correct": 1, "short": "0.52 ohm.", "expl": "No-load EMF = 12 × 2.1 = 25.2 V. Under load the terminal voltage = I × R_load = 10 × 2 = 20 V. The internal drop is 25.2 − 20 = 5.2 V, so internal resistance = 5.2 ÷ 10 = 0.52 Ω.", "cite": "FAA-H-8083-30B, p. 12-89", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8086", "q": "If electrolyte from a lead-acid battery is spilled in the battery compartment, which procedure should be followed?", "options": ["Apply boric acid solution to the affected area followed by a water rinse.", "Rinse the affected area thoroughly with clean water.", "Apply sodium bicarbonate solution to the affected area followed by a water rinse."], "correct": 2, "short": "Apply sodium bicarbonate solution to the affected area followed by a water rinse.", "expl": "Lead-acid electrolyte is sulfuric ACID, so you neutralize a spill with a base — sodium bicarbonate (baking soda) solution — then rinse with clean water. (Boric acid is for alkaline/ni-cad spills.)", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8087", "q": "Which statement regarding the hydrometer reading of a lead-acid storage battery electrolyte is true?", "options": ["The hydrometer reading does not require a temperature correction if the electrolyte temperature is 80°F.", "A specific gravity correction should be added to the hydrometer reading if the electrolyte temperature is below 59°F.", "The hydrometer reading will give a true indication of the capacity of the battery regardless of the electrolyte temperature."], "correct": 0, "short": "The hydrometer reading does not require a temperature correction if the electrolyte temperature is 80°F.", "expl": "Hydrometer specific-gravity readings are referenced to 80°F. At exactly 80°F no temperature correction is needed; above or below it you add or subtract a correction.", "cite": "FAA-H-8083-30B, p. 12-90", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8088", "q": "A fully charged lead-acid battery will not freeze until extremely low temperatures are reached because", "options": ["the acid is in the plates, thereby increasing the specific gravity of the solution.", "most of the acid is in the solution.", "increased internal resistance generates sufficient heat to prevent freezing."], "correct": 1, "short": "most of the acid is in the solution.", "expl": "A fully charged lead-acid battery has most of its acid dissolved in the electrolyte (high specific gravity), and that strong solution resists freezing until extremely cold. A discharged battery is mostly water and freezes easily.", "cite": "FAA-H-8083-30B, p. 12-90", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8089", "q": "What determines the amount of current which will flow through a battery while it is being charged by a constant voltage source?", "options": ["The total plate area of the battery.", "The ampere-hour capacity of the battery.", "The state-of-charge of the battery."], "correct": 2, "short": "The state-of-charge of the battery.", "expl": "Under constant-voltage charging, the battery's own state-of-charge sets the current: a low, discharged battery has low voltage and pulls a big charge current, which tapers as it fills.", "cite": "FAA-H-8083-30B, p. 12-91", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8090", "q": "Which of the following statements is false regarding the charging of several aircraft batteries together?", "options": ["Batteries of the same voltage and same amperehour capacity must be connected in series with each other across the charger and charged using the constant-current method.", "Batteries of different voltages (but similar capacities) can be connected in series with each other across the charger and charged using the constant-current method.", "Batteries of different ampere-hour capacity and same voltage can be connected in parallel with each other across the charger and charged using the constant-voltage method."], "correct": 0, "short": "Batteries of the same voltage and same amperehour capacity must be connected in series with each other across the charger and charged using the constant-current method.", "expl": "The FALSE statement is C. Same-voltage, same-capacity batteries are charged in PARALLEL by the constant-voltage method — not in series by constant-current. Series constant-current is for mixed/unequal batteries.", "cite": "FAA-H-8083-30B, p. 12-91", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8091", "q": "The method used to rapidly charge a nickel-cadmium battery utilizes", "options": ["constant current and constant voltage.", "constant voltage and varying current.", "constant current and varying voltage."], "correct": 1, "short": "constant voltage and varying current.", "expl": "Rapid-charging a nickel-cadmium battery uses a constant voltage while the current varies (tapers) as the cells come up to charge.", "cite": "FAA-H-8083-30B, p. 12-91", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8092", "q": "The purpose of providing a space underneath the plates in a lead acid batter’s cell container is to", "options": ["allow for convection of the electrolyte in order to provide for cooling of the plates.", "ensure that the electrolyte quantity ratio to the number of plates and plate area is adequate.", "prevent sediment buildup from contacting the plates and causing a short circuit."], "correct": 2, "short": "prevent sediment buildup from contacting the plates and causing a short circuit.", "expl": "The space under the plates in a lead-acid cell is a sediment trap: shed active material collects there instead of bridging the plates and shorting the cell.", "cite": "FAA-H-8083-30B, p. 12-87", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8093", "q": "Which condition is an indication of improperly torqued cell link connections of a nickel-cadmium battery?", "options": ["Heat or burn marks on the hardware.", "Light spewing at the cell caps.", "Toxic and corrosive deposits of potassium carbonate crystals."], "correct": 0, "short": "Heat or burn marks on the hardware.", "expl": "Loose (under-torqued) cell-link connections on a ni-cad run hot from the extra resistance. Heat or burn marks on the hardware are the tell-tale of an improperly torqued link.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8094", "q": "The presence of any small amount of potassium carbonate deposits on the top of nickel-cadmium battery cells in service is an indication of", "options": ["excessive gassing.", "normal operation.", "plate sulfation."], "correct": 1, "short": "normal operation.", "expl": "A small amount of white potassium-carbonate deposit on ni-cad cell tops is NORMAL — it comes from a little electrolyte spray and gassing, not from a fault.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8095", "q": "What is the likely result, if any, of servicing and charging nickel-cadmium and lead-acid batteries together in the same service area?", "options": ["The electrolytes in each battery are the same, so there are no significant differences.", "The nickel-cadmium would not be affected, but the lead-acid battery could become contaminated.", "Contamination of both types of batteries would occur."], "correct": 2, "short": "Contamination of both types of batteries would occur.", "expl": "Ni-cad electrolyte is an alkali (potassium hydroxide) and lead-acid is an acid; servicing them in the same area cross-contaminates BOTH types. Keep the two shops/areas separate.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8095-1", "q": "Which of the following best describes the operating principal in a nickel-cadmium battery installed in an aircraft?", "options": ["To completely charge a nickel-cadmium battery, some gassing must take place; thus, some water will be used.", "At full charge, the electrolyte will be at its lowest level and should be filled.", "When positive plates slowly give up oxygen, which is regained by the negative plates, the battery is charging."], "correct": 0, "short": "To completely charge a nickel-cadmium battery, some gassing must take place; thus, some water will be used.", "expl": "To fully charge a nickel-cadmium battery, some gassing has to occur near the end of charge, and that consumes a little water — which is why levels are checked when charged.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8096", "q": "The electrolyte of a nickel-cadmium battery is the lowest when the battery is", "options": ["being charged.", "in a discharged condition.", "under a heavy load condition."], "correct": 1, "short": "in a discharged condition.", "expl": "A ni-cad's electrolyte level is LOWEST when the battery is discharged (the electrolyte soaks into the plates). It rises again as the battery charges — the opposite of your lead-acid instinct.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8096-1", "q": "The electrolyte of a nickel-cadmium battery is highest when the battery is", "options": ["in a discharged condition.", "under a no-load condition.", "in a fully charged condition."], "correct": 2, "short": "in a fully charged condition.", "expl": "A ni-cad's electrolyte level is HIGHEST when fully charged (electrolyte comes back out of the plates). Never add water unless the battery is fully charged, or it will spew.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8097", "q": "The end-of-charge voltage of a 19-cell nickel-cadmium battery, measured while still on charge,", "options": ["depends upon its temperature and the method used for charging.", "must be 1.2 to 1.3 volts per cell.", "must be 1.4 volts per cell."], "correct": 0, "short": "depends upon its temperature and the method used for charging.", "expl": "The end-of-charge voltage of a 19-cell ni-cad has no single fixed number — it depends on the cell temperature and the charging method used.", "cite": "FAA-H-8083-30B, p. 12-91", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8098", "q": "During discharge, nickel-cadmium batteries will show a lower liquid level than when at full charge because", "options": ["a chemical action causes the electrolyte to evaporate through the vents.", "the electrolyte becomes absorbed into the plates.", "current leakage from individual cells causes a rise in temperature."], "correct": 1, "short": "the electrolyte becomes absorbed into the plates.", "expl": "During discharge a ni-cad's liquid level drops because the electrolyte is absorbed INTO the plates as they react — not from evaporation or leakage.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8099", "q": "How can the state-of-charge of a nickel-cadmium battery be determined?", "options": ["By measuring the specific gravity of the electrolyte.", "By the level of the electrolyte.", "By a measured discharge."], "correct": 2, "short": "By a measured discharge.", "expl": "You cannot judge a ni-cad's charge by electrolyte level or specific gravity (they don't track charge). The reliable method is a measured discharge — draw it down and time it against a known load.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8100", "q": "What may result if water is added to a nickel-cadmium battery when it is not fully charged?", "options": ["Excessive spewing is likely to occur during the charging cycle.", "Excessive electrolyte dilution.", "No adverse effects since water may be added anytime."], "correct": 0, "short": "Excessive spewing is likely to occur during the charging cycle.", "expl": "Adding water to a ni-cad that isn't fully charged overfills it, because the level rises during charge. The result is excessive spewing of electrolyte during the charging cycle.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8101", "q": "In nickel-cadmium batteries, a rise in cell temperature", "options": ["causes an increase in internal resistance.", "causes a decrease in internal resistance.", "increases cell voltage."], "correct": 1, "short": "causes a decrease in internal resistance.", "expl": "In ni-cads, voltage and internal resistance vary INVERSELY with temperature — as cell temperature rises, internal resistance DECREASES. Lower resistance lets in more current, which makes more heat: the thermal-runaway trap.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8101-1", "q": "Which of the following best describes the contributing factors to thermal runaway in a nickel-cadmium battery installed in an aircraft?", "options": ["High internal resistance intensified by high cell temperatures and a high current discharge/charge rate in a constant potential (voltage) charging system.", "Low internal resistance intensified by high cell temperatures and a high voltage discharge/charge rate in a constant current charging system.", "Low internal resistance intensified by high cell temperatures and a high current discharge/charge rate in a constant potential (voltage) charging system."], "correct": 2, "short": "Low internal resistance intensified by high cell temperatures and a high current discharge/charge rate in a constant potential (voltage) charging system.", "expl": "Thermal runaway comes from LOW internal resistance made worse by high cell temperature and a high current charge/discharge rate in a constant-potential (constant-voltage) charging system — a self-feeding heat loop.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8101-2", "q": "At what temperature is a battery charging adjustment necessary?", "options": ["95 degrees F.", "68 degrees F.", "25 degrees C."], "correct": 0, "short": "95 degrees F.", "expl": "A ni-cad battery-charging adjustment becomes necessary at 95°F — high temperature calls for reduced charging to avoid overheating.", "cite": "FAA-H-8083-30B, p. 12-91", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}, {"id": "8102", "q": "When a charging current is applied to a nickel cadmium battery, the cells emit gas", "options": ["throughout the charging cycle.", "toward the end of the charging cycle.", "especially if the electrolyte level is high."], "correct": 1, "short": "toward the end of the charging cycle.", "expl": "A charging ni-cad emits gas mainly toward the END of the charging cycle, once it approaches full charge and begins to overcharge slightly.", "cite": "FAA-H-8083-30B, p. 12-92", "topicName": "Batteries — Lead-Acid & Ni-Cad", "fig": null}]}, {"code": "SCHEM", "title": "Schematic & Wiring-Diagram Reading", "ref": "FAA-H-8083-30B Ch.12", "qs": [{"id": "8057", "q": "(Refer to Figure 15.) With the landing gear retracted, the red indicator light will not come on if an open occurs in wire", "options": ["19.", "7.", "17."], "correct": 0, "short": "19.", "expl": "Trace the red (gear-unsafe) light path in Figure 15 with the gear retracted: it runs through wire 19, so an open there kills the red light. Find power, find the light's ground, then follow the wire that feeds it.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "15"}, {"id": "8058", "q": "(Refer to Figure 15.) Wire 7 is used to", "options": ["open the UP indicator light circuit when the landing gear is retracted.", "close the PUSH-TO-TEST circuit.", "close the UP indicator light circuit when the landing gear is retracted."], "correct": 1, "short": "close the PUSH-TO-TEST circuit.", "expl": "Wire 7 in Figure 15 completes the PUSH-TO-TEST circuit — pressing test sends current through wire 7 to prove the lamp. Follow the test-switch branch on the drawing above.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "15"}, {"id": "8059", "q": "(Refer to Figure 15.) When the landing gear is down, the green light will not come on if an open occurs in wire", "options": ["7.", "17.", "6."], "correct": 2, "short": "6.", "expl": "With the gear down, the green (down-and-locked) light is fed through wire 6 in Figure 15, so an open in wire 6 stops the green light from coming on.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "15"}, {"id": "8060", "q": "(Refer to Figure 16.) What will be the effect if the PCO relay fails to operate when the left-hand tank is selected?", "options": ["The fuel pressure crossfeed valve open light will not illuminate.", "The fuel pressure crossfeed valve will not open.", "The fuel tank crossfeed valve open light will illuminate."], "correct": 0, "short": "The fuel pressure crossfeed valve open light will not illuminate.", "expl": "If the PCO relay never operates (Figure 16), the pump-crossfeed-valve-OPEN indicating path is never completed, so the crossfeed valve open light will NOT illuminate. Follow the dashed coil line to the contacts it moves.", "cite": "FAA-H-8083-30B, p. 12-33", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "16"}, {"id": "8061", "q": "(Refer to Figure 16.) The TCO relay will operate if 24-volts DC is applied to the bus and the fuel tank selector is in the", "options": ["right-hand tank position.", "crossfeed position.", "left-hand tank position."], "correct": 1, "short": "crossfeed position.", "expl": "In Figure 16 the TCO relay is energized when the fuel selector is in the CROSSFEED position and 24 V DC is on the bus — that's the selector setting that powers that coil.", "cite": "FAA-H-8083-30B, p. 12-33", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "16"}, {"id": "8062", "q": "(Refer to Figure 16.) With power to the bus and the fuel selector switched to the right-hand tank, how many relays in the system are operating?", "options": ["Two.", "Four.", "Three."], "correct": 2, "short": "Three.", "expl": "Walk Figure 16 with the selector on the right-hand tank: three relays end up energized. Follow the selector to the one coil it powers, then each relay it triggers in turn (the cascade).", "cite": "FAA-H-8083-30B, p. 12-33", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "16"}, {"id": "8063", "q": "(Refer to Figure 16.) When electrical power is applied to the bus, which relays are energized?", "options": ["PCC and TCC.", "TCC and TCO.", "PCO and PCC."], "correct": 0, "short": "PCC and TCC.", "expl": "The moment bus power is applied (before any tank is selected) in Figure 16, the PCC and PCO relays are the ones energized. Start at the bus and see which coils have a complete path with the selector at rest.", "cite": "FAA-H-8083-30B, p. 12-33", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "16"}, {"id": "8064", "q": "(Refer to Figure 16.) Energize the circuit with the fuel tank selector switch selected to the left-hand position. Using the schematic, identify the switches that will change position.", "options": ["5, 9, 10, 11, 12, 13, and 15.", "5, 6, 11, 12, 13, 15, and 16.", "3, 5, 6, 7, 11, and 13."], "correct": 1, "short": "5, 6, 11, 12, 13, 15, and 16.", "expl": "Selecting the left-hand tank in Figure 16 sets off the cascade: switches 5, 6, 11, 12, 13, 15, and 16 change position. The selector powers one coil, whose contacts feed the next, on down the chain — read it as small circuits triggering each other.", "cite": "FAA-H-8083-30B, p. 12-33", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "16"}, {"id": "8065", "q": "(Refer to Figure 17.) Which of the components is a potentiometer?", "options": ["5.", "11.", "3."], "correct": 2, "short": "3.", "expl": "In Figure 17, the potentiometer is component 3 — a resistor with a movable wiper arrow tapping off a variable voltage. (A rheostat/variable resistor uses two terminals; a potentiometer uses three.)", "cite": "FAA-H-8083-30B, p. 12-26", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "17"}, {"id": "8066", "q": "(Refer to Figure 17.) The electrical symbol represented at number 5 is a variable", "options": ["capacitor.", "inductor.", "resistor."], "correct": 0, "short": "capacitor.", "expl": "The symbol at number 5 in Figure 17 is a variable capacitor — two plates (the capacitor symbol) with an arrow through it showing it's adjustable.", "cite": "FAA-H-8083-30B, p. 12-53", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "17"}, {"id": "8067", "q": "(Refer to Figure 18.) When the landing gear is up and the throttles are retarded, the warning horn will not sound if an open occurs in wire", "options": ["2.", "4.", "9."], "correct": 1, "short": "4.", "expl": "Trace the warning-horn ground path in Figure 18 with the gear up and throttles retarded: it runs through wire 4, so an open in wire 4 keeps the horn from sounding.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "18"}, {"id": "8068", "q": "(Refer to Figure 18.) The control valve switch must be placed in the neutral position when the landing gear is down to", "options": ["permit the test circuit to operate.", "remove the ground from the green light.", "prevent the warning horn from sounding when the throttles are closed."], "correct": 2, "short": "prevent the warning horn from sounding when the throttles are closed.", "expl": "Putting the control-valve switch in NEUTRAL (Figure 18) breaks the horn's ground path, so the horn won't sound when the throttles are closed with the gear down — it prevents a false warning.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "18"}, {"id": "8069", "q": "(Refer to Figure 19.) Under which condition will a ground be provided for the warning horn through both gear switches when the throttles are closed?", "options": ["Left gear up and right gear down.", "Right gear up and left gear down.", "Both gears up and the control valve out of neutral."], "correct": 0, "short": "Left gear up and right gear down.", "expl": "In Figure 19 the horn gets a ground through BOTH gear switches only in one split-gear case: left gear up and right gear down (with the throttles closed). Check each gear-switch position on the drawing.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "19"}, {"id": "8070", "q": "(Refer to Figure 19.) When the throttles are retarded with only the right gear down, the warning horn will not sound if an open occurs in wire", "options": ["13.", "5.", "6."], "correct": 1, "short": "5.", "expl": "With only the right gear down and throttles retarded (Figure 19), the horn ground runs through wire 5, so an open in wire 5 silences the horn.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "19"}, {"id": "8071", "q": "(Refer to Figure 19.) When the landing gears are up and the throttles are retarded, the warning horn will not sound if an open occurs in wire", "options": ["5.", "7.", "6."], "correct": 2, "short": "6.", "expl": "With both gears up and throttles retarded (Figure 19), the horn's ground path passes through wire 6 — an open there stops the horn.", "cite": "FAA-H-8083-30B, p. 12-30", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "19"}, {"id": "8072", "q": "When referring to an electrical circuit diagram, what point is considered to be at zero voltage?", "options": ["The ground reference.", "The circuit breaker.", "The switch."], "correct": 0, "short": "The ground reference.", "expl": "On a circuit diagram, the point taken as zero voltage is the ground reference — every other voltage is measured relative to it.", "cite": "FAA-H-8083-30B, p. 12-14", "topicName": "Schematic & Wiring-Diagram Reading", "fig": null}, {"id": "8072-1", "q": "What is the purpose of the ground symbol used in electrical circuit diagrams?", "options": ["To show that there is common bus for connection of the source of electrical energy to the load.", "To show that there is a return path for the current between the source of electrical energy and the load.", "To show the source of electrical energy for the load."], "correct": 1, "short": "To show that there is a return path for the current between the source of electrical energy and the load.", "expl": "The ground symbol shows a common return path for current between the source of electrical energy and the load — the airframe/chassis acts as the return conductor.", "cite": "FAA-H-8083-30B, p. 12-23", "topicName": "Schematic & Wiring-Diagram Reading", "fig": null}, {"id": "8073", "q": "(Refer to Figure 20.) Troubleshooting an open circuit with a voltmeter as shown in this circuit will", "options": ["permit current to flow and illuminate the lamp.", "create a low resistance path and the current flow will be greater than normal.", "permit the battery voltage to appear on the voltmeter."], "correct": 2, "short": "permit the battery voltage to appear on the voltmeter.", "expl": "Troubleshooting an open with a voltmeter (Figure 20): with the meter bridging the open, the full battery voltage appears on the voltmeter, because there's no current and no drop anywhere else — the whole source shows across the break.", "cite": "FAA-H-8083-30B, p. 12-82", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "20"}, {"id": "8074", "q": "(Refer to Figure 21.) Which symbol represents a variable resistor?", "options": ["2.", "1.", "3."], "correct": 0, "short": "2.", "expl": "In Figure 21 the variable resistor is symbol 2 — a resistor with an arrow drawn diagonally THROUGH it (the wiper). Symbols with the tap coming off the top/side are potentiometer-style; the arrow-through-the-body is the variable resistor.", "cite": "FAA-H-8083-30B, p. 12-26", "topicName": "Schematic & Wiring-Diagram Reading", "fig": "21"}]}]};
